type Status = "menunggu" | "dibayar" | "dikirim";
type Pesanan = { id: number; status: Status };
const p1: Pesanan = { id: 1, status: "dibayar" };
const p2: Pesanan = { id: 2, status: "menunggu" };
console.log(p1.id, p1.status);
console.log(p2.id, p2.status);
